final class TaxonomyRouteRegistrar { public function __construct(private readonly ApiResponseFactory $responses,private readonly AuthService $auth){} public function register(App $app):void{$em=DoctrineEntityManagerFactory::create();$subjects=new DoctrineTaxonomySubjectRepository($em);$transactions=new DoctrineTransactionManager($em);$taxonomy=new SubjectTaxonomyService();$controller=new TaxonomyController($this->auth,new CreateTaxonomySubjectService($subjects,$taxonomy,new TaxonomySubjectResponseMapper(),$transactions),new ListTaxonomySubjectsService($subjects,new TaxonomySubjectResponseMapper()),new UpdateTaxonomySubjectService($subjects,$taxonomy,new TaxonomySubjectResponseMapper(),$transactions),$this->responses);$reconciliation=new TaxonomyReconciliationController($this->auth,new ListTaxonomyReconciliationProposalsService($subjects,new DeterministicTaxonomyReconciliationAdvisor($taxonomy)),$this->responses);$merges=new TaxonomySubjectMergeController($this->auth,new MergeTaxonomySubjectsService($subjects,new DoctrineTaxonomySubjectMergeApplier($em),new DoctrineTaxonomySubjectMergeRepository($em),$transactions),$this->responses);$suggestions=new TaxonomyDuplicateSuggestionController($this->auth,new ListTaxonomyDuplicateSuggestionsService($subjects,$taxonomy),$this->responses);$aliases=new TaxonomySubjectAliasController($this->auth,new CreateTaxonomySubjectAliasService($subjects,new DoctrineTaxonomySubjectAliasRepository($em),$taxonomy,new TaxonomySubjectAliasResponseMapper(),$transactions),$this->responses);$identity=new IdentityRequestFactory();$factory=new TaxonomyRequestFactory();$responses=$this->responses;$app->get('/v1/admin/taxonomy/subjects',static function(ServerRequestInterface $request,ResponseInterface $response)use($controller,$identity,$factory,$responses):ResponseInterface{try{return $controller->list($request,$response,$identity->accessToken($request),$factory->list($request));}catch(InvalidArgumentException $e){return $responses->problem($respons