,ResponseInterface $response)use($aliases,$identity,$factory,$responses):ResponseInterface{try{return $aliases->create($request,$response,$identity->accessToken($request),$factory->createAlias($request));}catch(InvalidArgumentException $e){return $responses->problem($response,'VALIDATION_FAILED','Um ou mais campos sao invalidos.',422,(string)$request->getAttribute('request_id'));}});} }
